// ValidateRegistry checks generated descriptors without publishing mutation authority.
func ValidateRegistry() error {
	for _, e := range Entities {
		if e.Ref == "" || e.Name == "" || e.Key == "" || e.OwnerDomain == "" || e.Class == "" || e.Status == "" || e.LifecycleAssignment == "" {
			return fmt.Errorf("invalid entity descriptor %s", e.Ref)
		}
		for _, p := range e.Properties {
			if p.Ref == "" || p.GoType == "" || p.SchemaPath == "" || p.Presence == "" || p.AuthorityRef == "" || p.RetentionClassRef == "" {
				return fmt.Errorf("invalid property descriptor %s", p.Ref)
			}
		}
	}
	for _, r := range Relationships {
		if r.Ref == "" || r.SourceEntity == "" || r.TargetEntity == "" || r.Cardinality == "" {
			return fmt.Errorf("invalid relationship descriptor %s", r.Ref)
		}
	}
	for _, a := range Authorities {
		if a.Ref == "" || a.Kind == "" || a.DomainScope == "" || a.Merge == "" || a.EvidenceRef == "" {
			return fmt.Errorf("invalid authority descriptor %s", a.Ref)
		}
	}
	for _, r := range Retentions {
		if r.Ref == "" || r.TriggerEvent == "" || r.DispositionOwner == "" || r.AuthorityRef == "" || (r.DefaultPeriodDays == 0 && len(r.JurisdictionOverrides) == 0) {
			return fmt.Errorf("invalid retention descriptor %s", r.Ref)
		}
	}
	return nil
}

// Entity resolves a generated entity descriptor by canonical reference.
func Entity(ref string) (EntityDescriptor, bool) {
	for _, e := range Entities {
		if e.Ref == ref {
			return e, true
		}
	}
	return EntityDescriptor{}, false
}

// Relationship resolves a generated relationship descriptor by reference.
func Relationship(ref string) (RelationDescriptor, bool) {
	for _, r := range Relationships {
		if r.Ref == ref {
			return r, true
		}
	}
	return RelationDescriptor{}, false
}
